window.ACTIVIDAD = {"id": "ut2-08-arregla-vitroceramica", "titulo": "Arregla la vitrocerámica", "subtitulo": "UT2 · Diseño y desarrollo web · 3º EAS Diseño Gráfico", "etiqueta": "UT2 · Diseño y desarrollo web", "objetivo": "Una fábrica de vitrocerámicas te pide arreglar sus paneles: cada mando debe estar donde la gente espera encontrarlo. Coloca los mandos para que reproduzcan la posición de los fuegos (mapeo natural) y explica por qué así se aprende antes a usarla.", "minutos": 10, "preguntasPorIntento": 8, "aprobado": 50, "garantizar": ["arrastrar", "arrastrar", "arrastrar"], "instrucciones": {"arrastrar": "Cada ficha es el mando de un fuego. Arrástrala al hueco del panel que corresponde a ese fuego. También puedes pulsar un mando y después su hueco. Sobra un mando. Cada hueco bien rellenado suma.", "emparejar": "Arrastra cada rasgo de usabilidad junto a la situación que describe. También puedes pulsar un rasgo y después su hueco. Sobra un rasgo. Cada pareja bien hecha suma."}, "diapositivas": {"111": "Introducción a la usabilidad: objetos difíciles de usar. La «tetera para masoquistas», con el asa y el pico en el mismo lado.", "113": "(No) Norman door: puerta con tiradores para tirar y el rótulo «PUSH» (empujar). Portada del libro «The Design of Everyday Things» de Don Norman.", "124": "Sin hacer un máster: el uso debe ser cómodo sean cuales sean los conocimientos técnicos y la experiencia del usuario. Si es necesario aprender a navegar por tu página, necesitas mejorarla. Si va en contra de lo que el usuario ya conoce, terminará por abandonarla.", "125": "La usabilidad aumenta cuando el usuario es capaz de predecir el funcionamiento al ver la web y cuando intuye la respuesta del sitio al interactuar con él.", "126": "Rasgos para la usabilidad. Consistencia: los elementos son coherentes en todas las páginas en diseño, funcionalidad y comportamiento. Persistencia: los elementos se colocan siempre en el mismo sitio y el mismo orden.", "130": "Rasgos para la usabilidad. Facilidad de aprendizaje: que el usuario pueda realizar las tareas desde el primer contacto con el sitio, o cuánto se tarda en aprender a usarlo.", "132": "Vitrocerámica de cuatro fuegos con los mandos táctiles agrupados: su disposición reproduce la de los fuegos.", "133": "Comparativa de las dos vitrocerámicas: ¿cuál permite saber a la primera qué mando controla cada fuego? La de los mandos agrupados como los fuegos (mapeo natural)."}, "banco": [{"id": "q01", "tipo": "arrastrar", "grupo": "panel-a", "pinesSoloNumero": true, "enunciado": "Esta vitrocerámica tiene cuatro fuegos. Coloca cada mando en el hueco que corresponde a su fuego. (El fuego doble tiene dos anillos; el alargado es ovalado).", "imagen": "img/panel-cuatro-a.svg", "alt": "Vitrocerámica de cuatro fuegos. Detrás a la izquierda, un fuego doble, el más grande, con dos anillos. Detrás a la derecha, un fuego mediano. Delante a la izquierda, un fuego pequeño. Delante a la derecha, un fuego grande. Entre los dos fuegos de delante hay un grupo de cuatro huecos para mandos en dos filas: Zona 1 arriba a la izquierda, Zona 2 arriba a la derecha, Zona 3 abajo a la izquierda y Zona 4 abajo a la derecha.", "zonas": [{"id": "z1", "x": 43.1, "y": 68.1, "correcta": "t1"}, {"id": "z2", "x": 56.9, "y": 68.1, "correcta": "t2"}, {"id": "z3", "x": 43.1, "y": 85.3, "correcta": "t3"}, {"id": "z4", "x": 56.9, "y": 85.3, "correcta": "t4"}], "terminos": [{"id": "t1", "texto": "Fuego doble"}, {"id": "t2", "texto": "Fuego mediano"}, {"id": "t3", "texto": "Fuego pequeño"}, {"id": "t4", "texto": "Fuego grande"}, {"id": "t5", "texto": "Fuego alargado"}], "explicacion": "Los huecos forman un cuadrado como los fuegos: el de arriba a la izquierda es el del fuego de detrás a la izquierda (el doble), y así con los demás. Es el mapeo natural de la diapositiva 132: el panel copia la posición de los fuegos y sabes a la primera qué mando enciende cada uno. Sobra el alargado: esta placa no tiene ninguno.", "diapositiva": 132}, {"id": "q02", "tipo": "arrastrar", "grupo": "panel-b", "pinesSoloNumero": true, "enunciado": "Esta vitrocerámica tiene tres fuegos. Coloca cada mando en el hueco que corresponde a su fuego. (El fuego doble tiene dos anillos; el alargado es ovalado).", "imagen": "img/panel-tres.svg", "alt": "Vitrocerámica de tres fuegos. Detrás a la izquierda, un fuego grande. Delante a la izquierda, un fuego pequeño. A la derecha, centrado de arriba abajo, un fuego mediano. Abajo, en el centro, un grupo de tres huecos para mandos: Zona 1 arriba a la izquierda, Zona 2 abajo a la izquierda y Zona 3 a la derecha, a media altura.", "zonas": [{"id": "z1", "x": 43.8, "y": 69.8, "correcta": "t1"}, {"id": "z2", "x": 43.8, "y": 87.1, "correcta": "t2"}, {"id": "z3", "x": 58.8, "y": 78.4, "correcta": "t3"}], "terminos": [{"id": "t1", "texto": "Fuego grande"}, {"id": "t2", "texto": "Fuego pequeño"}, {"id": "t3", "texto": "Fuego mediano"}, {"id": "t4", "texto": "Fuego doble"}], "explicacion": "Los tres huecos repiten la forma de la placa: dos a la izquierda (detrás el grande, delante el pequeño) y uno a la derecha, a media altura, como el fuego mediano. Así funciona el panel de la diapositiva 132. Sobra el doble: aquí ningún fuego tiene dos anillos.", "diapositiva": 132}, {"id": "q03", "tipo": "arrastrar", "grupo": "panel-c", "pinesSoloNumero": true, "enunciado": "Esta vitrocerámica tiene cinco fuegos, como la de la diapositiva 131. Coloca cada mando en el hueco que corresponde a su fuego. (El fuego doble tiene dos anillos; el alargado es ovalado).", "imagen": "img/panel-cinco.svg", "alt": "Vitrocerámica de cinco fuegos. Detrás a la izquierda, un fuego pequeño. Detrás a la derecha, un fuego alargado, ovalado. En el centro, un fuego doble, el más grande, con dos anillos. Delante a la izquierda, un fuego grande. Delante a la derecha, un fuego mediano. Debajo del fuego central hay un grupo de cinco huecos para mandos: Zona 1 arriba a la izquierda, Zona 2 arriba a la derecha, Zona 3 en el centro, Zona 4 abajo a la izquierda y Zona 5 abajo a la derecha.", "zonas": [{"id": "z1", "x": 43.0, "y": 67.7, "correcta": "t1"}, {"id": "z2", "x": 57.0, "y": 67.7, "correcta": "t2"}, {"id": "z3", "x": 50.0, "y": 78.7, "correcta": "t3"}, {"id": "z4", "x": 43.0, "y": 89.7, "correcta": "t4"}, {"id": "z5", "x": 57.0, "y": 89.7, "correcta": "t5"}], "terminos": [{"id": "t1", "texto": "Fuego pequeño"}, {"id": "t2", "texto": "Fuego alargado"}, {"id": "t3", "texto": "Fuego doble"}, {"id": "t4", "texto": "Fuego grande"}, {"id": "t5", "texto": "Fuego mediano"}, {"id": "t6", "texto": "Fuego triple"}], "explicacion": "Las cuatro esquinas del grupo de mandos son las cuatro esquinas de la placa y el hueco central es el fuego central (el doble). La vitrocerámica real de la diapositiva 131 pone sus cinco mandos en fila y hay que leer los iconos para saber cuál es cuál; con esta disposición se ve sin leer nada. Sobra el triple: no hay ningún fuego con tres anillos.", "diapositiva": 133}, {"id": "q04", "tipo": "arrastrar", "grupo": "panel-b", "pinesSoloNumero": true, "enunciado": "Esta vitrocerámica alargada tiene los cuatro fuegos en fila. Coloca cada mando en el hueco que corresponde a su fuego. (El fuego doble tiene dos anillos; el alargado es ovalado).", "imagen": "img/panel-fila.svg", "alt": "Vitrocerámica alargada con cuatro fuegos en una sola fila, de izquierda a derecha: un fuego grande, un fuego pequeño, un fuego doble con dos anillos (el más grande) y un fuego mediano. Debajo, una franja con cuatro huecos para mandos en fila, de izquierda a derecha: Zona 1, Zona 2, Zona 3 y Zona 4. Cada hueco está justo debajo de un fuego.", "zonas": [{"id": "z1", "x": 13.7, "y": 64.0, "correcta": "t1"}, {"id": "z2", "x": 37.5, "y": 64.0, "correcta": "t2"}, {"id": "z3", "x": 61.9, "y": 64.0, "correcta": "t3"}, {"id": "z4", "x": 86.3, "y": 64.0, "correcta": "t4"}], "terminos": [{"id": "t1", "texto": "Fuego grande"}, {"id": "t2", "texto": "Fuego pequeño"}, {"id": "t3", "texto": "Fuego doble"}, {"id": "t4", "texto": "Fuego mediano"}, {"id": "t5", "texto": "Fuego alargado"}], "explicacion": "Si los fuegos están en fila, los mandos en fila también son mapeo natural: cada mando queda justo debajo de su fuego. Lo que no funciona es una fila de mandos para fuegos colocados en cuadrado (diapositiva 131), porque una fila no puede indicar «detrás» y «delante». Sobra el alargado: no hay ningún fuego ovalado.", "diapositiva": 133}, {"id": "q05", "tipo": "arrastrar", "grupo": "panel-c", "pinesSoloNumero": true, "enunciado": "En esta vitrocerámica los mandos están en el lateral derecho. Coloca cada mando en el hueco que corresponde a su fuego. (El fuego doble tiene dos anillos; el alargado es ovalado).", "imagen": "img/panel-lateral.svg", "alt": "Vitrocerámica de cuatro fuegos. Detrás a la izquierda, un fuego grande. Detrás a la derecha, un fuego pequeño. Delante a la izquierda, un fuego alargado, ovalado. Delante a la derecha, un fuego doble con dos anillos. En el lateral derecho de la placa hay un grupo de cuatro huecos para mandos en dos filas: Zona 1 arriba a la izquierda, Zona 2 arriba a la derecha, Zona 3 abajo a la izquierda y Zona 4 abajo a la derecha.", "zonas": [{"id": "z1", "x": 76.7, "y": 38.9, "correcta": "t1"}, {"id": "z2", "x": 90.0, "y": 38.9, "correcta": "t2"}, {"id": "z3", "x": 76.7, "y": 61.1, "correcta": "t3"}, {"id": "z4", "x": 90.0, "y": 61.1, "correcta": "t4"}], "terminos": [{"id": "t1", "texto": "Fuego grande"}, {"id": "t2", "texto": "Fuego pequeño"}, {"id": "t3", "texto": "Fuego alargado"}, {"id": "t4", "texto": "Fuego doble"}, {"id": "t5", "texto": "Fuego mediano"}], "explicacion": "Aunque el grupo de mandos esté a un lado, sigue copiando la forma de la placa: arriba los fuegos de detrás y abajo los de delante; a la izquierda los de la izquierda y a la derecha los de la derecha. Lo que importa para el mapeo natural es la disposición, no el sitio del panel. Sobra el mediano: esta placa no lo tiene.", "diapositiva": 132}, {"id": "q06", "tipo": "arrastrar", "grupo": "panel-a", "pinesSoloNumero": true, "enunciado": "Otra vitrocerámica de cuatro fuegos. Coloca cada mando en el hueco que corresponde a su fuego. (El fuego doble tiene dos anillos; el alargado es ovalado).", "imagen": "img/panel-cuatro-b.svg", "alt": "Vitrocerámica de cuatro fuegos. Detrás a la izquierda, un fuego pequeño. Detrás a la derecha, un fuego doble, el más grande, con dos anillos. Delante a la izquierda, un fuego grande. Delante a la derecha, un fuego alargado, ovalado. Entre los dos fuegos de delante hay un grupo de cuatro huecos para mandos en dos filas: Zona 1 arriba a la izquierda, Zona 2 arriba a la derecha, Zona 3 abajo a la izquierda y Zona 4 abajo a la derecha.", "zonas": [{"id": "z1", "x": 43.1, "y": 68.1, "correcta": "t1"}, {"id": "z2", "x": 56.9, "y": 68.1, "correcta": "t2"}, {"id": "z3", "x": 43.1, "y": 85.3, "correcta": "t3"}, {"id": "z4", "x": 56.9, "y": 85.3, "correcta": "t4"}], "terminos": [{"id": "t1", "texto": "Fuego pequeño"}, {"id": "t2", "texto": "Fuego doble"}, {"id": "t3", "texto": "Fuego grande"}, {"id": "t4", "texto": "Fuego alargado"}, {"id": "t5", "texto": "Fuego mediano"}], "explicacion": "Los huecos de arriba son los fuegos de detrás (pequeño a la izquierda, doble a la derecha) y los de abajo, los de delante (grande y alargado). Es el mapeo natural de la diapositiva 132: no hace falta leer ni probar para saber qué mando enciende cada fuego. Sobra el mediano: esta placa no lo tiene.", "diapositiva": 132}, {"id": "q07", "tipo": "unica", "grupo": "comparar", "enunciado": "Las dos vitrocerámicas tienen los mismos fuegos. ¿Con cuál sabes a la primera qué mando enciende cada fuego?", "imagen": "img/comparativa.svg", "alt": "Dos vitrocerámicas iguales con cuatro fuegos en cuadrado. La A tiene sus cuatro mandos en una fila, en el borde de delante. La B tiene sus cuatro mandos en un cuadrado pequeño, entre los fuegos de delante.", "opciones": [{"id": "a", "texto": "Con la B, porque sus mandos están colocados igual que los fuegos.", "correcta": true}, {"id": "b", "texto": "Con la A, porque sus mandos están en orden, uno al lado de otro."}, {"id": "c", "texto": "Con las dos por igual, porque tienen el mismo número de mandos."}, {"id": "d", "texto": "Con ninguna de las dos, porque los mandos no llevan texto."}], "explicacion": "En la B, el mando de arriba a la izquierda es el del fuego de detrás a la izquierda, y así con todos: es el mapeo natural. En la A, una fila de cuatro no indica qué fuego es «detrás» y cuál «delante», así que hay que probar o leer el manual. Es la comparación de la diapositiva 133.", "diapositiva": 133}, {"id": "q08", "tipo": "unica", "grupo": "comparar", "enunciado": "Una vitrocerámica tiene los mandos colocados igual que los fuegos. ¿Qué rasgo de usabilidad mejora sobre todo?", "opciones": [{"id": "a", "texto": "La facilidad de aprendizaje.", "correcta": true}, {"id": "b", "texto": "La persistencia."}, {"id": "c", "texto": "La eficiencia."}, {"id": "d", "texto": "La consistencia."}], "explicacion": "La facilidad de aprendizaje mide si puedes hacer la tarea desde el primer contacto: con el mapeo natural, aciertas con el mando la primera vez. La persistencia es colocar los elementos siempre en el mismo sitio; la eficiencia, lo rápido que va quien ya conoce el diseño; la consistencia, que todo sea coherente en diseño y comportamiento. El temario pone la vitrocerámica como ejemplo de facilidad de aprendizaje.", "diapositiva": 130}, {"id": "q09", "tipo": "unica", "enunciado": "Elsa lleva cinco años con su vitrocerámica de mandos en fila y nunca se equivoca. Su primo Bruno la usa por primera vez y enciende un fuego que no es. ¿Qué rasgo de usabilidad falla para Bruno?", "opciones": [{"id": "a", "texto": "La facilidad de aprendizaje: no puede usarla bien desde el primer contacto.", "correcta": true}, {"id": "b", "texto": "La eficiencia: tarda mucho aunque ya conoce el diseño."}, {"id": "c", "texto": "La familiaridad: le recuerda demasiado a otra vitrocerámica."}, {"id": "d", "texto": "Ninguno: si Elsa la usa bien, es usable para todo el mundo."}], "explicacion": "Bruno es nuevo: lo que falla es la facilidad de aprendizaje, que es poder hacer la tarea desde el primer contacto. Elsa acierta porque ya ha aprendido, no porque el panel sea fácil. Por eso un panel con mapeo natural es mejor: sirve a la primera, también a quien no lo conoce.", "diapositiva": 130}, {"id": "q10", "tipo": "unica", "enunciado": "Cada mando lleva el número del fuego que enciende. ¿Qué problema tiene este panel?", "imagen": "img/panel-cruzado.svg", "alt": "Vitrocerámica de cuatro fuegos numerados: 1 detrás a la izquierda, 2 detrás a la derecha, 3 delante a la izquierda y 4 delante a la derecha. Los cuatro mandos están en un cuadrado. Fila de arriba: el mando 2 a la izquierda y el 1 a la derecha. Fila de abajo: el mando 4 a la izquierda y el 3 a la derecha.", "opciones": [{"id": "a", "texto": "Los mandos están cambiados de lado: el de la izquierda enciende un fuego de la derecha.", "correcta": true}, {"id": "b", "texto": "Los mandos están cambiados de fila: el de arriba enciende un fuego de delante."}, {"id": "c", "texto": "Hay más mandos que fuegos, así que uno no sirve para nada."}, {"id": "d", "texto": "No tiene ningún problema: los mandos están agrupados, como en la diapositiva 132."}], "explicacion": "Agrupar los mandos no basta: tienen que reproducir la posición de los fuegos. Aquí la izquierda y la derecha están cruzadas, así que la persona pulsará el mando que parece correcto y se encenderá otro fuego. Va contra lo que el usuario predice al ver el panel (diapositiva 125). Las filas sí están bien: arriba los fuegos de detrás y abajo los de delante.", "diapositiva": 125}, {"id": "q11", "tipo": "vf", "enunciado": "Si hay que leer el manual para saber qué mando enciende cada fuego, la vitrocerámica tiene buena facilidad de aprendizaje.", "correcta": false, "explicacion": "Falso. La facilidad de aprendizaje es poder hacer la tarea desde el primer contacto. Si necesitas el manual, el diseño no se entiende solo. El temario lo dice así para las webs: si es necesario aprender a navegar por tu página, necesitas mejorarla.", "diapositiva": 124}, {"id": "q12", "tipo": "vf", "grupo": "mapeo", "enunciado": "Hay mapeo natural cuando la disposición de los mandos reproduce la de las cosas que controlan, por ejemplo, la de los fuegos.", "correcta": true, "explicacion": "Verdadero. Con el mapeo natural, la posición del mando ya te dice qué controla: el de arriba a la izquierda enciende el fuego de detrás a la izquierda. No hace falta leer ni probar.", "diapositiva": 133}, {"id": "q13", "tipo": "unica", "grupo": "mapeo", "enunciado": "La diapositiva 125 dice que la usabilidad aumenta cuando el usuario puede predecir el funcionamiento al verlo. ¿Cómo lo consigue una vitrocerámica con los mandos colocados como los fuegos?", "opciones": [{"id": "a", "texto": "Antes de tocar nada, la posición del mando ya te dice qué fuego encenderá.", "correcta": true}, {"id": "b", "texto": "Cada mando tiene un texto que explica qué fuego enciende."}, {"id": "c", "texto": "Los mandos están siempre en el mismo sitio en todos los modelos de la marca."}, {"id": "d", "texto": "Al pulsar un mando, se ilumina el fuego que se ha encendido."}], "explicacion": "Predecir es saber qué pasará antes de actuar: eso lo da la disposición de los mandos. Un texto sirve, pero obliga a leer. Repetir el sitio en todos los modelos es persistencia o consistencia. Encender una luz al pulsar es la respuesta del sistema después de actuar, no una predicción.", "diapositiva": 125}, {"id": "q14", "tipo": "vf", "enunciado": "La «tetera para masoquistas» tiene el asa y el pico en el mismo lado. Es un objeto difícil de usar porque su forma impide hacer lo que promete: servir el té.", "correcta": true, "explicacion": "Verdadero. Es el ejemplo con el que el temario abre la usabilidad: un objeto puede ser bonito y aun así no servir para su objetivo. Igual que una vitrocerámica en la que no sabes qué mando enciende cada fuego.", "diapositiva": 111}, {"id": "q15", "tipo": "unica", "grupo": "norman", "enunciado": "Una puerta tiene tiradores grandes, que invitan a tirar, pero lleva un cartel de «PUSH» (empujar). ¿Cómo se llama este tipo de diseño en el temario?", "opciones": [{"id": "a", "texto": "Una puerta de Norman (Norman door).", "correcta": true}, {"id": "b", "texto": "Un mapeo natural."}, {"id": "c", "texto": "Una puerta de Nielsen."}, {"id": "d", "texto": "Un ejemplo de persistencia."}], "explicacion": "Se llama «Norman door» por Don Norman, autor de «The Design of Everyday Things». El tirador dice «tira» y el cartel dice «empuja»: si un objeto necesita un cartel para corregir lo que su forma comunica, está mal diseñado. Nielsen es el autor de los 10 heurísticos, no de este ejemplo.", "diapositiva": 113}, {"id": "q16", "tipo": "unica", "grupo": "norman", "enunciado": "¿Qué tienen en común la tetera con el asa y el pico en el mismo lado, la puerta de Norman y la vitrocerámica con los mandos en fila?", "opciones": [{"id": "a", "texto": "Al verlas no puedes saber bien cómo se usan.", "correcta": true}, {"id": "b", "texto": "Son objetos feos, sin ningún cuidado estético."}, {"id": "c", "texto": "Son objetos antiguos, de antes de que existiera el diseño."}, {"id": "d", "texto": "Solo fallan a quien no tiene conocimientos técnicos."}], "explicacion": "Los tres fallan en la usabilidad: su forma no deja predecir cómo usarlos o directamente lo impide. No es cuestión de estética ni de época. Y el temario insiste en que el uso debe ser cómodo sean cuales sean los conocimientos y la experiencia de cada persona.", "diapositiva": 113}, {"id": "q17", "tipo": "multiple", "enunciado": "La fábrica quiere que su próxima vitrocerámica se pueda usar bien desde el primer día. ¿Qué decisiones ayudan?", "opciones": [{"id": "a", "texto": "Colocar los mandos con la misma forma que los fuegos.", "correcta": true}, {"id": "b", "texto": "Si los fuegos están en fila, poner cada mando justo debajo de su fuego.", "correcta": true}, {"id": "c", "texto": "Poner todos los mandos en fila, en el orden en que se fabricaron los fuegos."}, {"id": "d", "texto": "Explicar en el manual qué mando corresponde a cada fuego, sin cambiar el panel."}], "explicacion": "Las dos primeras son mapeo natural: la posición del mando dice qué fuego enciende, en cuadrado o en fila. El orden de fabricación no lo conoce nadie que cocine. Y el manual no arregla el panel: si hay que aprender a usarlo, hay que mejorar el diseño (diapositiva 124).", "diapositiva": 133}, {"id": "q18", "tipo": "emparejar", "enunciado": "Empareja cada situación con el rasgo de usabilidad que muestra.", "pares": [{"id": "p1", "izquierda": "Usas bien la vitrocerámica nueva el primer día, sin mirar el manual.", "derecha": "Facilidad de aprendizaje"}, {"id": "p2", "izquierda": "El menú está arriba, en el mismo sitio y el mismo orden, en todas las páginas.", "derecha": "Persistencia"}, {"id": "p3", "izquierda": "La app de series se parece a otra que ya usas y te adaptas enseguida.", "derecha": "Familiaridad"}, {"id": "p4", "izquierda": "Ya conoces la tienda online y compras en pocos pasos, sin rodeos.", "derecha": "Eficiencia"}], "distractores": ["Utilidad"], "explicacion": "Usar algo bien desde el primer contacto es facilidad de aprendizaje. Mismo sitio y mismo orden es persistencia. Parecerse a algo que ya conoces es familiaridad (como Netflix y HBO Max). Conseguir tus metas rápido cuando ya conoces el diseño es eficiencia. Sobra la utilidad: es que el sistema cumpla de verdad sus objetivos, y ninguna situación habla de eso.", "diapositiva": 126}]};
